// A byte-array guard in the style of @noble/hashes' isBytes: instanceof
// first, then a structural fallback that reads BYTES_PER_ELEMENT.
export function isBytes(a) {
  return (
    a instanceof Uint8Array ||
    (ArrayBuffer.isView(a) && "BYTES_PER_ELEMENT" in a && a.BYTES_PER_ELEMENT === 1)
  );
}
export function elementSize(a) {
  return ArrayBuffer.isView(a) && "BYTES_PER_ELEMENT" in a ? a.BYTES_PER_ELEMENT : 0;
}
